import subprocess,sys
EXTRAS = {'auditar_y_habilitar.py': '', 'revisiones_fuentes.json': '', 'instalar_excepciones_robots.py': '', 'tests/test_auditar_y_habilitar.py': '', 'tests/test_excepciones_robots.py': '', 'fuente_jaguar.py': '', 'fuente_ticketsbravos.py': '', 'instalar_horarios_jaguar.py': '', 'reparar_agenda_hello.py': '', 'tests/test_fuente_jaguar.py': '', 'tests/test_ticketsbravos.py': ''}
for nombre,contenido in EXTRAS.items():
    p=Path(nombre)
    # Conservar revisiones particulares ya documentadas en el repositorio.
    if nombre == 'revisiones_fuentes.json' and p.exists():
        anterior=json.loads(p.read_text())
        inicial=json.loads(base64.b64decode(contenido))
        p.write_text(json.dumps({**inicial,**anterior},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    else:
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_bytes(base64.b64decode(contenido))
subprocess.run([sys.executable,'instalar_excepciones_robots.py'],check=True)
subprocess.run([sys.executable,'instalar_horarios_jaguar.py'],check=True)
p=Path('fuentes_nuevas.py');s=p.read_text(encoding='utf-8')
if '("Casa Brava", "Pichincha 120")' not in s:
    aguja='        ("Teatro Broadway", "San Lorenzo 1223"),'
    if aguja not in s:raise SystemExit('No se encontró ancla de Casa Brava')
    s=s.replace(aguja,aguja+'\n        ("Casa Brava", "Pichincha 120"),',1)
if '# TICKETS_BRAVOS_INTEGRACION_V1' not in s:
    aguja='    from fuentes_adicionales import revisar\n'
    if aguja not in s:raise SystemExit('No se encontró integración de fuentes adicionales')
    s=s.replace(aguja,'    # TICKETS_BRAVOS_INTEGRACION_V1\n    from fuente_ticketsbravos import revisar_ticketsbravos\n    nuevos.extend(revisar_ticketsbravos(hoy, estado))\n'+aguja,1)
p.write_text(s,encoding='utf-8')
# No ejecutar la siembra histórica de HELLO: las nuevas altas son dinámicas.
p=Path('.github/workflows/actualizar.yml');s=p.read_text()
for nombre in ['excepciones_robots.json','revisiones_fuentes.json','auditar_y_habilitar.py','fuente_jaguar.py','fuente_ticketsbravos.py']:
    entrada='      - '+nombre+'\n'
    if entrada not in s:s=s.replace('      - fuentes_ampliadas.py\n','      - fuentes_ampliadas.py\n'+entrada,1)
p.write_text(s)
print('Integración unificada instalada; las revisiones existentes y los eventos se conservan.')

